function parsePreisZuZahl(text) {
  if (!text) return 0;
  const match = String(text).replace(",", ".").match(/[\d]+(\.[\d]+)?/);
  return match ? parseFloat(match[0]) : 0;
}

function PayPalButton({ betrag, beschreibung, onErfolg }) {
  const containerRef = useRef(null);
  const [bereit, setBereit] = useState(false);
  const [fehler, setFehler] = useState("");

  useEffect(() => {
    if (window.paypal) { setBereit(true); return; }
    let script = document.getElementById("paypal-sdk-script");
    if (!script) {
      script = document.createElement("script");
      script.id = "paypal-sdk-script";
      script.src = `https://www.paypal.com/sdk/js?client-id=${PAYPAL_CLIENT_ID}&currency=EUR`;
      script.onerror = () => setFehler("PayPal konnte nicht geladen werden. Bitte Internetverbindung prüfen.");
      document.body.appendChild(script);
    }
    script.addEventListener("load", () => setBereit(true));
  }, []);

  useEffect(() => {
    if (!bereit || !containerRef.current || !window.paypal) return;
    containerRef.current.innerHTML = "";
    window.paypal.Buttons({
      style: { layout: "vertical", color: "gold", shape: "rect", label: "paypal", height: 45 },
      createOrder: async () => {
        const { data, error } = await supabase.functions.invoke("paypal-order", {
          body: { action: "create", amount: betrag.toFixed(2), description: beschreibung },
        });
        if (error || !data?.id) { setFehler("Bestellung konnte nicht erstellt werden."); throw new Error("create fehlgeschlagen"); }
        return data.id;
      },
      onApprove: async (data) => {
        const { data: capData, error } = await supabase.functions.invoke("paypal-order", {
          body: { action: "capture", orderID: data.orderID },
        });
        if (error || capData?.status !== "COMPLETED") { setFehler("Zahlung konnte nicht bestätigt werden."); return; }
        setFehler("");
        onErfolg(data.orderID);
      },
      onCancel: () => setFehler(""),
      onError: () => setFehler("Bei der PayPal-Zahlung ist ein Fehler aufgetreten."),
    }).render(containerRef.current);
  }, [bereit]);

  return (
    <div>
      <div className="text-center text-white font-bold text-sm mb-2">Zu zahlen: {betrag.toFixed(2)} €</div>
      <div ref={containerRef} />
      {!bereit && !fehler && <p className="text-zinc-500 text-xs text-center">PayPal wird geladen...</p>}
      {fehler && <p className="text-red-400 text-xs mt-2 text-center">{fehler}</p>}
    </div>
  );
}
