function getDeviceId() {
  let id = localStorage.getItem("padelhouse-device-id");
  if (!id) {
    id = crypto.randomUUID();
    localStorage.setItem("padelhouse-device-id", id);
  }
  return id;
}

async function loadKey(key, shared, fallback) {
  try {
    const scopeId = shared ? "shared" : getDeviceId();
    const { data, error } = await supabase
      .from("app_storage")
      .select("value")
      .eq("storage_key", key)
      .eq("scope_id", scopeId)
      .maybeSingle();
    if (error || !data) return fallback;
    return data.value;
  } catch (e) {
    return fallback;
  }
}
async function saveKey(key, shared, value) {
  try {
    const scopeId = shared ? "shared" : getDeviceId();
    await supabase.from("app_storage").upsert(
      { storage_key: key, scope_id: scopeId, value, updated_at: new Date().toISOString() },
      { onConflict: "storage_key,scope_id" }
    );
  } catch (e) {
    console.error("Speichern fehlgeschlagen:", key, e);
  }
}

function initialen(name) {
  if (!name) return "";
  const teile = name.trim().split(/\s+/);
  if (teile.length === 1) return teile[0].charAt(0).toUpperCase();
  return (teile[0].charAt(0) + teile[teile.length - 1].charAt(0)).toUpperCase();
}
function emptyTableRow(team) {
  return { teamId: team.id, name: team.name, sp: 0, s: 0, n: 0, saetzeP: 0, saetzeG: 0, pkt: 0 };
}
function computeTable(spiele, teams, ligaId) {
  const rows = {};
  teams.forEach((t) => (rows[t.id] = emptyTableRow(t)));
  spiele.forEach((sp) => {
    if (sp.ligaId !== ligaId) return;
    if (!sp.ergebnis || !sp.bestaetigt) return;
    const sets = sp.ergebnis.split(",").map((s) => s.trim()).filter(Boolean);
    let hS = 0, gS = 0;
    sets.forEach((set) => {
      const [a, b] = set.split(":").map((n) => parseInt(n, 10));
      if (isNaN(a) || isNaN(b)) return;
      if (a > b) hS++; else if (b > a) gS++;
    });
    const heim = rows[sp.heimId], gast = rows[sp.gastId];
    if (!heim || !gast) return;
    heim.sp++; gast.sp++;
    heim.saetzeP += hS; heim.saetzeG += gS;
    gast.saetzeP += gS; gast.saetzeG += hS;
    // Offizielle Punktevergabe (analog gängiger Padel-Ligen): Sieg 2:0-Sätze = 3 Punkte,
    // Sieg 2:1 = 2 Punkte, Niederlage 1:2 = 1 Punkt, Niederlage 0:2 = 0 Punkte.
    if (hS > gS) {
      heim.s++; gast.n++;
      heim.pkt += gS === 0 ? 3 : 2;
      gast.pkt += gS === 0 ? 0 : 1;
    } else if (gS > hS) {
      gast.s++; heim.n++;
      gast.pkt += hS === 0 ? 3 : 2;
      heim.pkt += hS === 0 ? 0 : 1;
    }
  });
  return Object.values(rows).sort((a, b) =>
    b.pkt - a.pkt ||
    b.s - a.s ||
    (b.saetzeP - b.saetzeG) - (a.saetzeP - a.saetzeG)
  );
}

