function FirmenbenefitView({ anfragen, onSave }) {
  const [form, setForm] = useState({ vorname: "", nachname: "", geburtsdatum: "", email: "", anbieter: "Wellpass", anbieterId: "" });
  const [error, setError] = useState("");
  const [mailLink, setMailLink] = useState(null);
  const [waLink, setWaLink] = useState(null);
  const [done, setDone] = useState(false);

  function submit(e) {
    e.preventDefault();
    if (!form.vorname.trim() || !form.nachname.trim() || !form.geburtsdatum || !form.email.trim() || !form.anbieterId.trim()) {
      setError("Bitte alle Felder ausfüllen.");
      return;
    }
    setError("");
    onSave([...anfragen, { id: "b-" + Date.now(), ...form }]);
    const text = `Firmenbenefit-Registrierung\nVorname: ${form.vorname}\nNachname: ${form.nachname}\nGeburtsdatum: ${form.geburtsdatum}\nE-Mail (Playtomic): ${form.email}\nAnbieter: ${form.anbieter}\nAnbieter-ID: ${form.anbieterId}`;
    setMailLink(mailtoLink(`Firmenbenefit-Registrierung: ${form.anbieter}`, text));
    setWaLink(whatsappLink(text));
    setDone(true);
    setForm({ vorname: "", nachname: "", geburtsdatum: "", email: "", anbieter: "Wellpass", anbieterId: "" });
  }

  return (
    <div>
      <p className="text-zinc-400 text-sm mb-4">Registrierung für Wellpass oder Hansefit. Die E-Mail muss dieselbe sein wie in deinem Playtomic-Profil.</p>

      {done && (
        <div className="bg-zinc-900 border border-emerald-700 rounded-lg p-4 mb-4 text-sm text-emerald-400 space-y-3">
          <p>Registrierung gespeichert. Sende sie jetzt per E-Mail oder WhatsApp an den Betreiber ab.</p>
          <div className="flex gap-2">
            {mailLink && <a href={mailLink} className="flex-1 text-center px-4 py-2 rounded-lg bg-emerald-500 text-white text-sm font-bold uppercase tracking-wide">E-Mail öffnen</a>}
            {waLink && <a href={waLink} target="_blank" rel="noopener noreferrer" className="flex-1 text-center px-4 py-2 rounded-lg bg-zinc-800 text-emerald-400 text-sm font-bold uppercase tracking-wide">WhatsApp öffnen</a>}
          </div>
        </div>
      )}

      <form onSubmit={submit} className="space-y-3">
        <Field label="Vorname"><input className={inputCls} value={form.vorname} onChange={(e) => setForm({ ...form, vorname: e.target.value })} /></Field>
        <Field label="Nachname"><input className={inputCls} value={form.nachname} onChange={(e) => setForm({ ...form, nachname: e.target.value })} /></Field>
        <Field label="Geburtsdatum"><input className={inputCls} type="date" value={form.geburtsdatum} onChange={(e) => setForm({ ...form, geburtsdatum: e.target.value })} /></Field>
        <Field label="E-Mail (muss identisch mit Playtomic sein)"><input className={inputCls} type="email" value={form.email} onChange={(e) => setForm({ ...form, email: e.target.value })} placeholder="name@email.de" /></Field>
        <Field label="Anbieter">
          <select className={inputCls} value={form.anbieter} onChange={(e) => setForm({ ...form, anbieter: e.target.value })}>
            <option value="Wellpass">Wellpass</option>
            <option value="Hansefit">Hansefit</option>
          </select>
        </Field>
        <Field label={"ID des Anbieters (" + form.anbieter + ")"}>
          <input className={inputCls} value={form.anbieterId} onChange={(e) => setForm({ ...form, anbieterId: e.target.value })} placeholder="Mitglieds-/Vertrags-ID" />
        </Field>
        {error && <p className="text-red-400 text-xs">{error}</p>}
        <button type="submit" className="w-full py-2 rounded-lg bg-emerald-500 text-white text-sm font-bold uppercase tracking-wide">Registrieren</button>
      </form>
    </div>
  );
}

function WuenscheView({ ideen, onSave, role, onMarkRead }) {
  const [form, setForm] = useState({ text: "", name: "" });
  const [liked, setLiked] = useState({});
  const [commentDrafts, setCommentDrafts] = useState({});
  const [mailLink, setMailLink] = useState(null);
  const [waLink, setWaLink] = useState(null);

  useEffect(() => { onMarkRead(ideen.length); }, [ideen.length]);

  function submit(e) {
    e.preventDefault();
    if (!form.text.trim()) return;
    onSave([...ideen, { id: "w-" + Date.now(), text: form.text, name: form.name || "Anonym", likes: 0, status: "in_pruefung", comment: "" }]);
    const text = `Neue Idee im Padelhouse\nIdee: ${form.text}\nVon: ${form.name || "Anonym"}`;
    setMailLink(mailtoLink("Neue Idee im Padelhouse", text));
    setWaLink(whatsappLink(text));
    setForm({ text: "", name: "" });
  }
  function like(id) {
    if (liked[id]) return;
    setLiked({ ...liked, [id]: true });
    onSave(ideen.map((i) => i.id === id ? { ...i, likes: i.likes + 1 } : i));
  }
  function cycleStatus(id) {
    onSave(ideen.map((i) => {
      if (i.id !== id) return i;
      const idx = STATUS_ORDER.indexOf(i.status);
      return { ...i, status: STATUS_ORDER[(idx + 1) % STATUS_ORDER.length] };
    }));
  }
  function saveComment(id) {
    onSave(ideen.map((i) => i.id === id ? { ...i, comment: commentDrafts[id] ?? i.comment } : i));
  }

  const sorted = ideen.slice().sort((a, b) => b.likes - a.likes);

  return (
    <div>
      <form onSubmit={submit} className="bg-zinc-900 border border-zinc-800 rounded-lg p-4 space-y-2 mb-5">
        <textarea className={inputCls} placeholder="Deine Idee..." rows={2} value={form.text} onChange={(e) => setForm({ ...form, text: e.target.value })} />
        <input className={inputCls} placeholder="Name (optional)" value={form.name} onChange={(e) => setForm({ ...form, name: e.target.value })} />
        <button type="submit" className="w-full py-2 rounded-lg bg-emerald-500 text-white text-sm font-bold uppercase tracking-wide">Idee einreichen</button>
        {(mailLink || waLink) && (
          <div className="flex gap-2">
            {mailLink && (
              <a href={mailLink} className="flex-1 text-center px-4 py-2 rounded-lg bg-zinc-800 text-emerald-400 text-sm font-bold uppercase tracking-wide">
                E-Mail öffnen
              </a>
            )}
            {waLink && (
              <a href={waLink} target="_blank" rel="noopener noreferrer" className="flex-1 text-center px-4 py-2 rounded-lg bg-zinc-800 text-emerald-400 text-sm font-bold uppercase tracking-wide">
                WhatsApp öffnen
              </a>
            )}
          </div>
        )}
      </form>

      <div className="space-y-3">
        {sorted.map((idea) => {
          const meta = STATUS_META[idea.status];
          return (
            <div key={idea.id} className="bg-zinc-900 border border-zinc-800 rounded-lg p-4">
              <div className="flex items-start gap-3">
                <button onClick={() => role === "admin" && cycleStatus(idea.id)} title={meta.label}
                  className={"mt-1 w-4 h-4 rounded-full border-2 shrink-0 " + meta.cls} />
                <div className="flex-1">
                  <div className="text-zinc-200 text-sm">{idea.text}</div>
                  <div className="text-zinc-500 text-xs mt-1">{idea.name} · {meta.label}</div>
                  {idea.comment && <div className="text-emerald-400 text-xs mt-2 border-l-2 border-emerald-700 pl-2">{idea.comment}</div>}
                  {role === "admin" && (
                    <div className="mt-2 flex gap-2">
                      <input className={inputCls} placeholder="Antwort/Kommentar" value={commentDrafts[idea.id] ?? idea.comment}
                        onChange={(e) => setCommentDrafts({ ...commentDrafts, [idea.id]: e.target.value })} />
                      <button onClick={() => saveComment(idea.id)} className="px-3 rounded-lg bg-emerald-500 text-white text-xs font-bold">OK</button>
                    </div>
                  )}
                </div>
                <button onClick={() => like(idea.id)} disabled={liked[idea.id]} className="flex flex-col items-center text-emerald-400 disabled:opacity-40">
                  <span>👍</span><span className="text-xs">{idea.likes}</span>
                </button>
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
}

